private function createUserToken(string $suffix, array $campusIds, string $email): string
{
    $user = User::create([
        'LoginName' => $email,
        'Name' => "test-user-{$suffix}",
        'PSW' => bcrypt('test'),
        'type' => 'A',
        'status' => 'active',
    ]);
    foreach ($campusIds as $cid) {
        UserCampus::firstOrCreate(
            ['UserID' => $user->id, 'CampusID' => $cid],
            ['Admin' => 1, 'Approved' => 1]
        );
